// ═══ BEFORE JEP 513 — super() must be first ═══
class Trade extends BaseEntity {
    Trade(String id, BigDecimal amount) {
        super(id);  // MUST be first line!
        // Can't validate id before calling super!
        if (id == null) throw new IllegalArgumentException("id null");  // too late — super already called!
    }
}

// ═══ AFTER JEP 513 (Java 24) — statements before super() ═══
class Trade extends BaseEntity {
    Trade(String id, BigDecimal amount) {
        // Validate BEFORE constructing:
        if (id == null || id.isBlank()) {
            throw new IllegalArgumentException("Trade ID cannot be null or blank");
        }
        if (amount.signum() < 0) {
            throw new IllegalArgumentException("Amount cannot be negative: " + amount);
        }
        // Compute derived value:
        String normalizedId = id.strip().toUpperCase();

        // NOW call super with validated, normalized arguments:
        super(normalizedId);

        this.amount = amount;
    }
}

// ═══ WORKAROUND BEFORE JEP 513 — static factory method ═══
class Trade extends BaseEntity {
    static Trade create(String id, BigDecimal amount) {
        if (id == null) throw new IllegalArgumentException("null id");
        return new Trade(id.strip().toUpperCase(), amount);
    }
    private Trade(String id, BigDecimal amount) {
        super(id);
        this.amount = amount;
    }
}
