package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class FlexibleCtorTest {

    static class Account {
        final BigDecimal balance;
        Account(BigDecimal balance) { this.balance = balance; }
    }
    static class SavingsAccount extends Account {
        SavingsAccount(BigDecimal opening) {
            // validate BEFORE super(...) (JEP 513 flexible constructor body)
            if (opening.signum() < 0) throw new IllegalArgumentException("negative opening");
            super(opening);
        }
    }

    @Test
    void validateBeforeSuper() {
        assertThat(new SavingsAccount(new BigDecimal("1000")).balance)
            .isEqualByComparingTo("1000");
        assertThatThrownBy(() -> new SavingsAccount(new BigDecimal("-1")))
            .isInstanceOf(IllegalArgumentException.class);
    }
}
